(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-172":{scenario:{company:"Riverbend Commercial Bank",supervisor:{name:"Hoàng Thị Lan Anh",role:{vi:"Trưởng phòng Thẩm định Tín dụng",en:"Head of Credit Underwriting"}},ref_code:"UW-5521",title:{vi:"Đọc đủ CIC. Tính đúng nhu cầu vốn.",en:"Read the full CIC. Size the real need."},brief:{vi:"Bạn thẩm định hồ sơ UW-5521: doanh nghiệp sản xuất đồ gỗ xin hạn mức vốn lưu động. Báo cáo CIC có một khoản vay tại ngân hàng khác quá hạn 40 ngày. Kế hoạch năm tới: chi phí sản xuất kinh doanh (không gồm khấu hao) 98400 triệu đồng, vòng quay vốn lưu động 4 vòng, vốn lưu động ròng tự có 7350 triệu, vay ngắn hạn tại tổ chức tín dụng khác 5150 triệu. Bản nháp ghi CIC-1 và hạn mức bằng toàn bộ nhu cầu vốn. Hãy sửa hai trường và lập báo cáo.",en:"You are underwriting file UW-5521: a furniture manufacturer requests a working capital line. The CIC report shows a loan at another bank 40 days past due. Next year's plan: operating costs excluding depreciation 98400 million VND, working capital turnover 4 times, own net working capital 7350 million, short-term loans at other credit institutions 5150 million. The draft records CIC-1 and a limit equal to the full need. Correct both fields and report."},reference_title:{vi:"Báo cáo CIC & bảng tính nhu cầu vốn đã duyệt · UW-5521",en:"Approved CIC report & working capital worksheet · UW-5521"},fields:[{id:"CIC_GROUP",label:{vi:"Nhóm nợ theo CIC",en:"CIC debt group"},initial:"CIC-1",expected:"CIC-2",choices:["CIC-1","CIC-2","CIC-3"],reference:"Báo cáo CIC & quy tắc phân nhóm nợ",ref_value:{vi:"Nhóm 1: quá hạn dưới 10 ngày; nhóm 2: từ 10 đến 90 ngày; nhóm 3: từ 91 đến 180 ngày",en:"Group 1: under 10 days past due; group 2: 10 to 90 days; group 3: 91 to 180 days"},hint:{vi:"Đọc chi tiết từng khoản vay trên CIC, không chỉ dòng tổng hợp; xếp theo số ngày quá hạn lớn nhất.",en:"Read each facility on the CIC report, not just the summary line; classify by the longest days past due."}},{id:"WC_LIMIT",label:{vi:"Hạn mức vốn lưu động (triệu đồng)",en:"Working capital limit (million VND)"},initial:"24600",expected:"12100",reference:"Bảng tính nhu cầu vốn lưu động",ref_value:{vi:"Chi phí 98400; vòng quay 4; VLĐ ròng tự có 7350; vay TCTD khác 5150 (triệu đồng)",en:"Costs 98400; turnover 4; own net working capital 7350; other lenders 5150 (million VND)"},hint:{vi:"Nhu cầu vốn lưu động chưa phải là hạn mức: phải trừ phần vốn tự có và phần vay ở nơi khác.",en:"The working capital need is not the limit: deduct own funds and borrowings elsewhere."}}],sop32:{vi:"Nhu cầu vốn lưu động = chi phí sản xuất kinh doanh (không gồm khấu hao) / vòng quay vốn lưu động; hạn mức = nhu cầu - vốn lưu động ròng tự có - vay ngắn hạn tại tổ chức tín dụng khác.",en:"Working capital need = operating costs excluding depreciation / working capital turnover; limit = need - own net working capital - short-term loans at other credit institutions."},context:{label:"LOS / UW-5521",metrics:[{label:{vi:"Chi phí kế hoạch",en:"Planned costs"},value:"98,400,000,000 VND"},{label:{vi:"Vòng quay vốn lưu động",en:"Working capital turnover"},value:"4.0x"},{label:{vi:"Quá hạn trên CIC",en:"CIC past due"},value:"40 DPD"}]},crisis:{vi:"RM gửi thêm một bộ báo cáo tài chính có doanh thu cao hơn 35% so với bản đã nộp cơ quan thuế và nhắn: “Dùng bộ này cho hồ sơ đẹp, giám đốc chi nhánh đã đồng ý miệng. Chiều nay phải trình hội đồng tín dụng.”",en:"The RM sends a second set of financial statements with revenue 35% higher than the version filed with the tax authority: “Use this set so the file looks better. The branch director agreed verbally and it goes to the credit committee this afternoon.”"},options:{safe:{vi:"Chỉ dùng báo cáo đã nộp thuế hoặc đã kiểm toán, ghi nhận chênh lệch là dấu hiệu rủi ro, yêu cầu khách giải trình bằng văn bản và báo Trưởng phòng Thẩm định.",en:"Use only the tax-filed or audited statements, record the gap as a red flag, request a written explanation from the client and inform the Head of Underwriting."},shortcut:{vi:"Dùng bộ báo cáo đẹp hơn vì đã có giám đốc chi nhánh đồng ý miệng.",en:"Use the better-looking set because the branch director agreed verbally."},wait:{vi:"Hoãn trình hồ sơ, không ghi nhận chênh lệch và không báo cho ai.",en:"Delay the file without recording the gap or telling anyone."}},questions:{vi:["Vì sao khách hàng thuộc nhóm CIC-2 và hạn mức chỉ là 12100 triệu đồng? Trình bày dữ liệu và công thức.","Hai bộ báo cáo tài chính khác nhau báo hiệu rủi ro gì và bạn xử lý theo quy trình nào?"],en:["Why is the client in CIC-2 and why is the limit only 12100 million VND? Show the data and the formula.","What risk do two different sets of financial statements signal and which procedure do you follow?"]},hints:{vi:["Rà từng dòng chi tiết trên báo cáo CIC và tìm số ngày quá hạn lớn nhất.","Tính nhu cầu vốn lưu động trước, rồi trừ hai nguồn vốn khác theo SOP mục 3.2.","Đọc SOP mục 4.2: số liệu tài chính không nhất quán phải được ghi nhận và báo cáo, không tự chọn bản đẹp."],en:["Scan each detail line of the CIC report and find the longest days past due.","Compute the working capital need first, then deduct the two other funding sources in SOP 3.2.","Re-read SOP 4.2: inconsistent financial data must be recorded and escalated, never cherry-picked."]}},learning:{summary:{vi:"Chuyên viên thẩm định tín dụng đánh giá độc lập hồ sơ vay: tư cách pháp lý, lịch sử tín dụng trên CIC, năng lực tài chính, phương án kinh doanh, dòng tiền trả nợ và tài sản bảo đảm, từ đó đề xuất cấp, điều chỉnh hoặc từ chối tín dụng kèm điều kiện kiểm soát. Nghề bảo vệ chất lượng tài sản của ngân hàng, đòi hỏi kỹ năng phân tích tài chính, hoài nghi nghề nghiệp và tính độc lập với bộ phận kinh doanh.",en:"A credit underwriter independently assesses loan applications: legal standing, CIC credit history, financial capacity, business plan, repayment cash flow and collateral, then recommends approval, restructuring or rejection with control conditions. The role protects the bank's asset quality and requires financial analysis skills, professional scepticism and independence from the sales function."},responsibilities:{vi:["Kiểm tra tư cách pháp lý, mục đích vay và tính hợp pháp của phương án.","Phân tích báo cáo tài chính, dòng tiền và khả năng trả nợ của khách hàng.","Tra cứu, đánh giá lịch sử tín dụng trên CIC và quan hệ với các tổ chức tín dụng khác.","Xác định nhu cầu vốn, hạn mức, kỳ hạn và điều kiện cấp tín dụng.","Lập báo cáo thẩm định độc lập, nêu rõ rủi ro và biện pháp kiểm soát."],en:["Check legal standing, loan purpose and the legality of the business plan.","Analyse financial statements, cash flow and debt service capacity.","Pull and assess CIC credit history and relationships with other lenders.","Size the funding need, limit, tenor and credit conditions.","Write an independent underwriting report stating risks and mitigants."]},competencies:[{name:{vi:"Phân tích báo cáo tài chính",en:"Financial statement analysis"},desc:{vi:"Đánh giá thanh khoản, đòn bẩy, hiệu quả, chất lượng lợi nhuận và phát hiện số liệu bất thường.",en:"Assess liquidity, leverage, efficiency and earnings quality, and spot unusual figures."}},{name:{vi:"Đánh giá dòng tiền trả nợ",en:"Repayment cash flow"},desc:{vi:"Dự phóng dòng tiền, tính DSCR và nhu cầu vốn lưu động sát thực tế.",en:"Project cash flows, calculate DSCR and a realistic working capital need."}},{name:{vi:"Đọc lịch sử tín dụng",en:"Credit history review"},desc:{vi:"Đọc chi tiết CIC, nhận diện nợ quá hạn, nợ cơ cấu và quan hệ với nhiều ngân hàng.",en:"Read the CIC in detail and identify past-due, restructured and multi-bank exposures."}},{name:{vi:"Hoài nghi nghề nghiệp",en:"Professional scepticism"},desc:{vi:"Đối chiếu chéo báo cáo thuế, kiểm toán, sao kê ngân hàng trước khi tin số liệu.",en:"Cross-check tax filings, audits and bank statements before trusting figures."}},{name:{vi:"Độc lập & chính trực",en:"Independence & integrity"},desc:{vi:"Đưa kết luận dựa trên bằng chứng dù chịu áp lực từ kinh doanh hay lãnh đạo chi nhánh.",en:"Base conclusions on evidence despite pressure from sales or branch management."}}],knowledge:{vi:["Thông tư 11/2021/TT-NHNN về phân loại nợ, trích lập dự phòng và việc điều chỉnh nhóm nợ theo thông tin từ CIC.","Phương pháp xác định nhu cầu vốn lưu động theo vòng quay và hạn mức tín dụng.","Phân tích báo cáo tài chính: thanh khoản, đòn bẩy, hiệu quả hoạt động, DSCR và lưu chuyển tiền.","Mô hình 5C trong tín dụng: tư cách, năng lực, vốn, tài sản bảo đảm và điều kiện.","Quy định hiện hành về giới hạn cấp tín dụng đối với một khách hàng và người có liên quan."],en:["Circular 11/2021/TT-NHNN on loan classification, provisioning and aligning debt groups with CIC data.","The turnover method for sizing working capital needs and credit limits.","Financial statement analysis: liquidity, leverage, efficiency, DSCR and cash flow.","The 5C credit model: character, capacity, capital, collateral and conditions.","Current single-borrower and related-party lending limits."]},tools:["CIC credit report","Loan Origination System (LOS)","Internal credit rating model","Financial spreading tool","Cash flow projection model","Collateral management system"],tools_en:["CIC credit report","Loan Origination System (LOS)","Internal credit rating model","Financial spreading tool","Cash flow projection model","Collateral management system"],kpis:{vi:["Tỷ lệ nợ xấu phát sinh từ các khoản đã thẩm định sau 12 tháng.","Thời gian thẩm định trung bình mỗi hồ sơ.","Tỷ lệ hồ sơ bị kiểm toán nội bộ phát hiện sai sót trọng yếu.","Tỷ lệ cảnh báo rủi ro được nêu trong báo cáo và xác nhận về sau."],en:["Non-performing ratio of underwritten loans after 12 months.","Average underwriting time per file.","Share of files with material errors found by internal audit.","Share of flagged risks later confirmed."]},day:[{time:"08:00",vi:"Nhận hồ sơ mới, kiểm tra danh mục chứng từ còn thiếu.",en:"Receive new files and list missing documents."},{time:"09:30",vi:"Tra cứu CIC, đối chiếu dư nợ và nhóm nợ tại các ngân hàng khác.",en:"Pull the CIC report and match balances and debt groups at other banks."},{time:"11:00",vi:"Nhập và phân tích báo cáo tài chính, tính nhu cầu vốn lưu động.",en:"Spread and analyse financial statements and size the working capital need."},{time:"14:00",vi:"Khảo sát thực tế cơ sở sản xuất, kho hàng và tài sản bảo đảm.",en:"Visit the production site, warehouse and collateral."},{time:"16:30",vi:"Hoàn thiện báo cáo thẩm định và trình hội đồng tín dụng.",en:"Finalise the underwriting report and submit it to the credit committee."}],mistakes:{vi:["Chỉ đọc dòng tổng hợp trên CIC, bỏ sót khoản quá hạn tại ngân hàng khác.","Lấy nhu cầu vốn lưu động làm hạn mức mà không trừ vốn tự có và vay nơi khác.","Tin báo cáo tài chính do khách tự lập mà không đối chiếu với bản nộp thuế hoặc kiểm toán."],en:["Reading only the CIC summary and missing a past-due loan at another bank.","Using the working capital need as the limit without deducting own funds and other loans.","Trusting client-prepared statements without checking tax-filed or audited versions."]},career:[{vi:"Chuyên viên thẩm định tín dụng",en:"Credit underwriter"},{vi:"Chuyên viên thẩm định cao cấp",en:"Senior credit underwriter"},{vi:"Trưởng phòng Thẩm định / Phê duyệt tín dụng",en:"Head of underwriting or credit approval"},{vi:"Giám đốc Khối Quản lý tín dụng",en:"Chief Credit Officer"}],glossary:[{term:"CIC",vi:"Trung tâm Thông tin tín dụng Quốc gia, cung cấp lịch sử vay và nhóm nợ của khách hàng.",en:"Vietnam's National Credit Information Centre, which reports borrowers' credit history and debt groups."},{term:"DSCR",vi:"Hệ số khả năng trả nợ: dòng tiền dành trả nợ chia cho gốc và lãi phải trả trong kỳ.",en:"Debt service coverage ratio: cash flow available for debt service divided by principal and interest due."},{term:"Working capital turnover",vi:"Số vòng quay vốn lưu động trong năm, bằng doanh thu thuần chia vốn lưu động bình quân.",en:"Times working capital turns over in a year, net revenue divided by average working capital."},{term:"5C",vi:"Năm tiêu chí đánh giá tín dụng: tư cách, năng lực, vốn, tài sản bảo đảm, điều kiện.",en:"Five credit criteria: character, capacity, capital, collateral and conditions."},{term:"Covenant",vi:"Cam kết tài chính hoặc hành vi khách hàng phải duy trì trong suốt thời gian vay.",en:"A financial or behavioural undertaking the borrower must maintain during the loan."}],quiz:[{q:{vi:"Khoản vay quá hạn 120 ngày được xếp nhóm nợ nào theo quy định phân loại nợ hiện hành?",en:"Under current classification rules, which debt group applies to a loan 120 days past due?"},options:{vi:["Nhóm 2","Nhóm 4","Nhóm 3","Nhóm 5"],en:["Group 2","Group 4","Group 3","Group 5"]},answer:2,explain:{vi:"Nợ quá hạn từ 91 đến 180 ngày thuộc nhóm 3 (nợ dưới tiêu chuẩn).",en:"Loans 91 to 180 days past due are group 3 (substandard)."}},{q:{vi:"Chi phí sản xuất kinh doanh 60000 triệu, vòng quay vốn lưu động 5, vốn tự có 4000, vay nơi khác 2000. Hạn mức là bao nhiêu?",en:"Operating costs 60000 million, turnover 5, own funds 4000, other loans 2000. What is the limit?"},options:{vi:["6000 triệu","12000 triệu","8000 triệu","10000 triệu"],en:["6000 million","12000 million","8000 million","10000 million"]},answer:0,explain:{vi:"Nhu cầu = 60000 / 5 = 12000; hạn mức = 12000 - 4000 - 2000 = 6000 triệu đồng.",en:"Need = 60000 / 5 = 12000; limit = 12000 - 4000 - 2000 = 6000 million."}},{q:{vi:"Hệ số DSCR dưới 1 cho biết điều gì?",en:"What does a DSCR below 1 indicate?"},options:{vi:["Doanh nghiệp có lãi cao","Tài sản bảo đảm đủ","Vòng quay hàng tồn kho nhanh","Dòng tiền không đủ trả gốc và lãi đến hạn"],en:["High profitability","Sufficient collateral","Fast inventory turnover","Cash flow cannot cover principal and interest due"]},answer:3,explain:{vi:"DSCR dưới 1 nghĩa là dòng tiền tạo ra nhỏ hơn nghĩa vụ trả nợ trong kỳ.",en:"A DSCR below 1 means generated cash flow is less than debt service due."}},{q:{vi:"Khách hàng có hai bộ báo cáo tài chính khác nhau. Bạn nên làm gì?",en:"A client has two different sets of financial statements. What should you do?"},options:{vi:["Dùng bộ có số liệu tốt hơn","Ghi nhận chênh lệch, dùng bản đã nộp thuế hoặc kiểm toán và báo cáo cấp trên","Lấy trung bình hai bộ","Bỏ qua vì RM đã xác nhận"],en:["Use the better set","Record the gap, use the tax-filed or audited set and escalate","Average the two sets","Ignore it because the RM confirmed"]},answer:1,explain:{vi:"Chênh lệch số liệu là dấu hiệu gian lận; phải dùng nguồn tin cậy, yêu cầu giải trình và báo cáo.",en:"Inconsistent figures are a fraud red flag; use reliable sources, request explanations and escalate."}}]}}})})(window.KKR);
